import java.util.ArrayList;
import java.util.List;
import java.util.stream.Stream;

/**
 * TASK: Generate finite sequences with the three-argument Stream.iterate
 * (seed, hasNext predicate, next function) -- no limit() and no while loop.
 *
 * doublingUpTo(seed, limit): seed, seed*2, seed*4, ... while the value is <= limit.
 *   doublingUpTo(1, 20) -> [1, 2, 4, 8, 16]
 *   doublingUpTo(5, 3)  -> []            (the seed already fails the test)
 *
 * collatzSteps(start): how many steps it takes to reach 1, where an even
 * number halves and an odd number becomes 3n + 1.
 *   collatzSteps(6) -> 8   (6, 3, 10, 5, 16, 8, 4, 2, 1 -- nine values, eight steps)
 *   collatzSteps(1) -> 0
 */
public class SeriesGenerator {

    public static List<Integer> doublingUpTo(int seed, int limit) {
        return Stream.iterate(seed, n -> n <= limit, n -> n * 2)
                .collect(java.util.stream.Collectors.toList());
    }

    public static long collatzSteps(int start) {
        return Stream.iterate(start, n -> n != 1, n -> n % 2 == 0 ? n / 2 : 3 * n + 1)
                .count();
    }
}
